import { CommonModule, DatePipe, NgFor, NgIf } from '@angular/common';
import { Component, OnInit, inject } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { ResourceItem, ResourceService } from '../../core/services/resource.service';
import { MovementHistory, Tire, TireService } from '../../core/services/tire.service';
import { NotificationService } from '../../core/services/notification.service';

@Component({
  selector: 'app-tires',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, NgFor, NgIf, DatePipe],
  template: `
    <section class="page-header">
      <div>
        <span class="eyebrow">Inventario</span>
        <h2>Gestion de gomas y ubicaciones</h2>
      </div>
    </section>

    <section class="panel-grid two-columns">
      <article class="panel-card">
        <div class="panel-head">
          <h3>Filtros rapidos</h3>
        </div>
        <form class="inline-form" [formGroup]="filtersForm">
          <input type="text" placeholder="Buscar por codigo, marca o medida" formControlName="search" />
          <select formControlName="state">
            <option value="">Todos los estados</option>
            <option value="NUEVA">Nueva</option>
            <option value="USADA">Usada</option>
            <option value="REPARADA">Reparada</option>
            <option value="BAJA">Baja</option>
          </select>
          <select formControlName="locationType">
            <option value="">Todas las ubicaciones</option>
            <option value="DEPOSIT">Deposito</option>
            <option value="SEMI">Semi</option>
            <option value="TRACTOR">Tractor</option>
          </select>
          <button class="secondary-button" type="button" (click)="loadTires()">Aplicar</button>
        </form>
      </article>

      <article class="panel-card">
        <div class="panel-head">
          <h3>{{ editingId ? 'Editar goma' : 'Nueva goma' }}</h3>
        </div>
        <form class="form-grid" [formGroup]="tireForm" (ngSubmit)="saveTire()">
          <input type="text" placeholder="Codigo unico" formControlName="code" />
          <input type="text" placeholder="Marca" formControlName="brand" />
          <input type="text" placeholder="Modelo" formControlName="model" />
          <input type="text" placeholder="Medida" formControlName="size" />
          <select formControlName="state">
            <option value="NUEVA">Nueva</option>
            <option value="USADA">Usada</option>
            <option value="REPARADA">Reparada</option>
            <option value="BAJA">Baja</option>
          </select>
          <select formControlName="currentLocation">
            <option value="DEPOSIT">Deposito</option>
            <option value="SEMI">Semi</option>
            <option value="TRACTOR">Tractor</option>
          </select>
          <select *ngIf="tireForm.value.currentLocation === 'DEPOSIT'" formControlName="depositId">
            <option value="">Seleccionar deposito</option>
            <option *ngFor="let deposit of deposits" [value]="deposit.id">{{ deposit.name }}</option>
          </select>
          <select *ngIf="tireForm.value.currentLocation === 'SEMI'" formControlName="semiId">
            <option value="">Seleccionar semi</option>
            <option *ngFor="let semi of semis" [value]="semi.id">{{ semi.plate }}</option>
          </select>
          <select *ngIf="tireForm.value.currentLocation === 'TRACTOR'" formControlName="tractorId">
            <option value="">Seleccionar tractor</option>
            <option *ngFor="let tractor of tractors" [value]="tractor.id">{{ tractor.plate }}</option>
          </select>
          <textarea rows="3" placeholder="Observaciones" formControlName="notes"></textarea>
          <div class="form-actions">
            <button class="primary-button" type="submit">{{ editingId ? 'Actualizar' : 'Guardar' }}</button>
            <button class="ghost-button" type="button" (click)="resetForm()">Limpiar</button>
          </div>
        </form>
      </article>
    </section>

    <section class="panel-grid two-columns">
      <article class="panel-card">
        <div class="panel-head">
          <h3>Stock actual</h3>
        </div>
        <div class="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>Codigo</th>
                <th>Marca</th>
                <th>Modelo</th>
                <th>Medida</th>
                <th>Estado</th>
                <th>Ubicacion</th>
                <th>Acciones</th>
              </tr>
            </thead>
            <tbody>
              <tr *ngFor="let tire of tires">
                <td>{{ tire.code }}</td>
                <td>{{ tire.brand }}</td>
                <td>{{ tire.model }}</td>
                <td>{{ tire.size }}</td>
                <td><span class="chip">{{ tire.state }}</span></td>
                <td>{{ tire.locationDetail.label }}</td>
                <td class="actions-cell">
                  <button class="ghost-button" type="button" (click)="editTire(tire)">Editar</button>
                  <button class="ghost-button danger" type="button" (click)="showHistory(tire)">Historial</button>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </article>

      <article class="panel-card">
        <div class="panel-head">
          <h3>{{ selectedTire?.code ? 'Historial de ' + selectedTire?.code : 'Historial' }}</h3>
        </div>
        <div class="timeline" *ngIf="history.length; else emptyHistory">
          <div class="timeline-item" *ngFor="let item of history">
            <div>
              <strong>{{ item.previousLocation }} → {{ item.newLocation }}</strong>
              <p>{{ item.previousPlate || 'Sin patente' }} → {{ item.newPlate || 'Sin patente' }}</p>
              <p>{{ item.notes || 'Sin observaciones' }}</p>
            </div>
            <small>{{ item.user.name }} · {{ item.createdAt | date:'short' }}</small>
          </div>
        </div>
        <ng-template #emptyHistory>
          <p class="empty-state">Selecciona una goma para ver su historial de movimientos.</p>
        </ng-template>
      </article>
    </section>
  `,
})
export class TiresComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly tireService = inject(TireService);
  private readonly resourceService = inject(ResourceService);
  private readonly notificationService = inject(NotificationService);

  tires: Tire[] = [];
  history: MovementHistory[] = [];
  selectedTire: Tire | null = null;
  editingId: string | null = null;
  deposits: ResourceItem[] = [];
  tractors: ResourceItem[] = [];
  semis: ResourceItem[] = [];

  readonly filtersForm = this.fb.nonNullable.group({
    search: [''],
    state: [''],
    locationType: [''],
  });

  readonly tireForm = this.fb.nonNullable.group({
    code: ['', Validators.required],
    brand: ['', Validators.required],
    model: ['', Validators.required],
    size: ['', Validators.required],
    state: ['NUEVA', Validators.required],
    currentLocation: ['DEPOSIT', Validators.required],
    depositId: [''],
    semiId: [''],
    tractorId: [''],
    notes: [''],
  });

  ngOnInit(): void {
    this.loadResources();
    this.loadTires();
  }

  loadResources(): void {
    this.resourceService.getDeposits().subscribe((items) => (this.deposits = items));
    this.resourceService.getTractors().subscribe((items) => (this.tractors = items));
    this.resourceService.getSemis().subscribe((items) => (this.semis = items));
  }

  loadTires(): void {
    this.tireService.getAll(this.filtersForm.getRawValue()).subscribe((items) => (this.tires = items));
  }

  saveTire(): void {
    if (this.tireForm.invalid) {
      this.tireForm.markAllAsTouched();
      return;
    }

    const payload = this.tireForm.getRawValue();
    const request = this.editingId
      ? this.tireService.update(this.editingId, payload)
      : this.tireService.create(payload);

    request.subscribe({
      next: () => {
        this.notificationService.show('success', this.editingId ? 'Goma actualizada.' : 'Goma registrada.');
        this.resetForm();
        this.loadTires();
      },
      error: (error) => {
        this.notificationService.show('error', error.error?.message || 'No se pudo guardar la goma.');
      },
    });
  }

  editTire(tire: Tire): void {
    this.editingId = tire.id;
    this.tireForm.patchValue({
      code: tire.code,
      brand: tire.brand,
      model: tire.model,
      size: tire.size,
      state: tire.state,
      currentLocation: tire.currentLocation,
      notes: tire.notes || '',
    });
  }

  showHistory(tire: Tire): void {
    this.selectedTire = tire;
    this.tireService.getHistory(tire.id).subscribe((history) => (this.history = history));
  }

  resetForm(): void {
    this.editingId = null;
    this.tireForm.reset({
      code: '',
      brand: '',
      model: '',
      size: '',
      state: 'NUEVA',
      currentLocation: 'DEPOSIT',
      depositId: '',
      semiId: '',
      tractorId: '',
      notes: '',
    });
  }
}
